interface Service { String get(String k); }
class SlowService implements Service {
    public String get(String k) { return "result:" + k; }
}
class CacheProxy implements Service {
    private Service real; private Map<String,String> cache = new java.util.HashMap<>();
    CacheProxy(Service s) { real = s; }
    public String get(String k) { return cache.computeIfAbsent(k, real::get); }
}

