public class StructuralPatterns2 {
    static class ManaSystem { void check() { System.out.println("Mana OK"); } }
    static class ArcaneChannel { void open() { System.out.println("Channel open"); } }
    static class SpellcastingFacade {
        private ManaSystem mana = new ManaSystem();
        private ArcaneChannel channel = new ArcaneChannel();
        void castSpell() {
            mana.check();
            channel.open();
            System.out.println("Spell cast!");
        }
    }
    public static void main(String[] args) {
        new SpellcastingFacade().castSpell();
    }
}
